/* S-box width of each circuit: 4 means present_circuit_<backend>_cN,
 * 8 means present_circuit8_<backend>_cN. The two have different arities,
 * so the kernel that calls one is specialised on this. */
static const int present_circuit_sbox_bits[PRESENT_N_CIRCUITS] = {
    8, 8, 8, 8, 4, 4, 4, 4, 4, 4, 4, 4, 4, 4
};

/* Circuit i computes S(x) ^ present_circuit_outcomp[i], nibble-wise: bit j set
 * means output bit j comes out complemented. Both backends share the mask.
 * present_core.c cancels it in the round keys, so callers see plain S. */
static const int present_circuit_outcomp[PRESENT_N_CIRCUITS] = {
    0x0, 0x0, 0x0, 0x0, 0xc, 0x5, 0x7, 0x4, 0x3, 0xc, 0x0, 0x0, 0x5, 0x3
};

